//! A facade marked with `#[tool]`, its tools generated by `#[seiva::tools]` and
//! served over MCP: listing and calling by the person's own permissions, the BOLA
//! scope through `Ctx`, the human approval of a write, and the audit.

use std::sync::{Arc, Mutex};

use axum::body::Body;
use axum::http::{Request, StatusCode};
use seiva::{facade, tools, WireSchema};
use seiva_contract::Problem;
use seiva_http::Ctx;
use seiva_identity::{Principal, TokenAuthenticator};
use seiva_mcp_server::{McpServer, ToolSet, APPROVAL_ARG, PROTOCOL_VERSION};
use seiva_ports::{AuditEntry, AuditSink, PortResult};
use seiva_testing::RecordingAuditSink;
use serde::{Deserialize, Serialize};
use serde_json::{json, Value};
use tower::ServiceExt;

/// Command DTO: refund part of a payment.
#[derive(Debug, Clone, Deserialize, Serialize, WireSchema)]
pub struct RefundPayment {
    pub payment: String,
    pub amount_cents: u64,
}

/// A refund, as returned.
#[derive(Debug, Clone, Deserialize, Serialize, WireSchema)]
pub struct RefundDto {
    pub payment: String,
    pub amount_cents: u64,
    pub by: String,
}

/// A payment, as shown.
#[derive(Debug, Clone, Deserialize, Serialize, WireSchema)]
pub struct PaymentView {
    pub id: String,
    pub tenant: String,
    pub seen_by: String,
}

#[derive(Debug)]
pub enum PayError {
    NotFound,
}

impl From<PayError> for Problem {
    fn from(_: PayError) -> Self {
        Problem::not_found("no such payment")
    }
}

#[facade(version = "v1")]
pub trait Payments {
    /// Show a payment by its id.
    #[requires("payments.read")]
    #[tool(effect = "read")]
    async fn show(&self, ctx: &Ctx, id: String) -> Result<PaymentView, PayError>;

    /// Refund a captured payment, fully or partly. The money goes back to the
    /// customer's card.
    #[requires("payments.refund")]
    #[tool(effect = "write")]
    async fn refund(&self, ctx: &Ctx, cmd: RefundPayment) -> Result<RefundDto, PayError>;

    /// Delete old payments. Not an agent tool.
    #[requires("payments.admin")]
    async fn purge(&self, ctx: &Ctx) -> Result<u32, PayError>;
}

#[derive(Clone, Default)]
struct Service {
    refunds: Arc<Mutex<Vec<(String, String, u64)>>>,
}

#[tools]
impl Payments for Service {
    async fn show(&self, ctx: &Ctx, id: String) -> Result<PaymentView, PayError> {
        // The payment belongs to tenant acme: another tenant does not see it (BOLA).
        if ctx.tenant() != Some("acme") {
            return Err(PayError::NotFound);
        }
        Ok(PaymentView {
            id,
            tenant: "acme".into(),
            seen_by: ctx.principal().subject.clone(),
        })
    }

    async fn refund(&self, ctx: &Ctx, cmd: RefundPayment) -> Result<RefundDto, PayError> {
        let by = ctx.principal().subject.clone();
        self.refunds
            .lock()
            .unwrap()
            .push((by.clone(), cmd.payment.clone(), cmd.amount_cents));
        Ok(RefundDto {
            payment: cmd.payment,
            amount_cents: cmd.amount_cents,
            by,
        })
    }

    async fn purge(&self, _ctx: &Ctx) -> Result<u32, PayError> {
        Ok(0)
    }
}

const ANA: &str = "token-ana";
const BOB: &str = "token-bob";
const READER: &str = "token-reader";
const OTHER_TENANT: &str = "token-zeta";

struct Fixture {
    app: axum::Router,
    service: Service,
}

fn fixture_with(
    configure: impl FnOnce(seiva_mcp_server::McpServerBuilder) -> seiva_mcp_server::McpServerBuilder,
) -> Fixture {
    fixture_audit(Arc::new(RecordingAuditSink::new()), configure)
}

fn fixture_audit(
    audit: Arc<dyn AuditSink>,
    configure: impl FnOnce(seiva_mcp_server::McpServerBuilder) -> seiva_mcp_server::McpServerBuilder,
) -> Fixture {
    let service = Service::default();
    let tools = ToolSet::new()
        .with(payments_tools(service.clone()))
        .unwrap();
    let auth = TokenAuthenticator::new()
        .with_token(
            ANA,
            Principal::in_tenant("ana", "acme", ["payments.read", "payments.refund"]),
        )
        .with_token(
            BOB,
            Principal::in_tenant(
                "bob",
                "acme",
                ["payments.read", "payments.refund", "payments.refund.auto"],
            ),
        )
        .with_token(
            READER,
            Principal::in_tenant("rui", "acme", ["payments.read"]),
        )
        .with_token(
            OTHER_TENANT,
            Principal::in_tenant("zeca", "zeta", ["payments.read"]),
        );
    let server = configure(
        McpServer::builder(tools, Arc::new(auth), audit).resource("https://api.example.com/mcp"),
    )
    .build();
    Fixture {
        app: server.router(),
        service,
    }
}

async fn send(
    app: &axum::Router,
    method: &str,
    path: &str,
    token: Option<&str>,
    body: Option<Value>,
) -> (StatusCode, Value, axum::http::HeaderMap) {
    let mut req = Request::builder()
        .method(method)
        .uri(path)
        .header("content-type", "application/json");
    if let Some(t) = token {
        req = req.header("authorization", format!("Bearer {t}"));
    }
    let res = app
        .clone()
        .oneshot(
            req.body(body.map_or_else(Body::empty, |b| Body::from(b.to_string())))
                .unwrap(),
        )
        .await
        .unwrap();
    let status = res.status();
    let headers = res.headers().clone();
    let bytes = axum::body::to_bytes(res.into_body(), usize::MAX)
        .await
        .unwrap();
    (
        status,
        serde_json::from_slice(&bytes).unwrap_or(Value::Null),
        headers,
    )
}

async fn rpc(app: &axum::Router, token: &str, method: &str, params: Value) -> Value {
    let (status, body, _) = send(
        app,
        "POST",
        "/mcp",
        Some(token),
        Some(json!({"jsonrpc": "2.0", "id": 1, "method": method, "params": params})),
    )
    .await;
    assert_eq!(status, StatusCode::OK, "{body}");
    body
}

async fn call(app: &axum::Router, token: &str, tool: &str, args: Value) -> Value {
    rpc(
        app,
        token,
        "tools/call",
        json!({"name": tool, "arguments": args}),
    )
    .await
}

#[tokio::test]
async fn tools_come_from_the_facade_and_are_listed_by_permission() {
    let f = fixture_with(|b| b);
    let init = rpc(
        &f.app,
        ANA,
        "initialize",
        json!({"protocolVersion": PROTOCOL_VERSION, "capabilities": {}}),
    )
    .await;
    assert_eq!(init["result"]["protocolVersion"], PROTOCOL_VERSION);

    let list = rpc(&f.app, ANA, "tools/list", json!({})).await;
    let tools = list["result"]["tools"].as_array().unwrap();
    let names: Vec<&str> = tools.iter().map(|t| t["name"].as_str().unwrap()).collect();
    assert_eq!(
        names,
        vec!["payments_refund", "payments_show"],
        "purge is not a tool"
    );
    let refund = &tools[0];
    assert_eq!(
        refund["description"],
        "Refund a captured payment, fully or partly. The money goes back to the customer's card."
    );
    assert_eq!(refund["annotations"]["destructiveHint"], true);
    // The DTO's own schema is the input: its fields are the arguments.
    assert_eq!(
        refund["inputSchema"]["properties"]["amount_cents"]["type"],
        "integer"
    );
    let show = &tools[1];
    assert_eq!(show["inputSchema"]["properties"]["id"]["type"], "string");
    assert_eq!(show["annotations"]["readOnlyHint"], true);

    // Rui may only read: the refund tool is neither listed nor callable.
    let list = rpc(&f.app, READER, "tools/list", json!({})).await;
    assert_eq!(list["result"]["tools"].as_array().unwrap().len(), 1);
    let err = call(
        &f.app,
        READER,
        "payments_refund",
        json!({"payment": "P-1", "amount_cents": 1}),
    )
    .await;
    assert_eq!(err["error"]["code"], -32602);
    assert!(f.service.refunds.lock().unwrap().is_empty());
}

#[tokio::test]
async fn a_read_tool_runs_as_the_person_with_their_tenant_scope() {
    let f = fixture_with(|b| b);
    let res = call(&f.app, ANA, "payments_show", json!({"id": "P-1"})).await;
    assert_eq!(res["result"]["isError"], false, "{res}");
    assert_eq!(
        res["result"]["structuredContent"],
        json!({"id": "P-1", "tenant": "acme", "seen_by": "ana"})
    );
    // Another tenant gets the facade's own 404, as over HTTP.
    let res = call(&f.app, OTHER_TENANT, "payments_show", json!({"id": "P-1"})).await;
    assert_eq!(res["result"]["isError"], true);
    assert!(res["result"]["content"][0]["text"]
        .as_str()
        .unwrap()
        .contains("404"));
    // Wrong arguments are the tool's error, not a crash.
    let res = call(&f.app, ANA, "payments_show", json!({"identifier": 7})).await;
    assert_eq!(res["result"]["isError"], true);
}

#[tokio::test]
async fn a_write_waits_for_the_persons_approval_and_runs_once() {
    let audit = RecordingAuditSink::new();
    let f = fixture_audit(Arc::new(audit.clone()), |b| b);
    let args = json!({"payment": "P-1", "amount_cents": 500});

    let first = call(&f.app, ANA, "payments_refund", args.clone()).await;
    assert_eq!(first["result"]["isError"], true);
    let id = first["result"]["structuredContent"]["approval_required"]["id"]
        .as_str()
        .unwrap()
        .to_owned();
    assert!(f.service.refunds.lock().unwrap().is_empty(), "nothing ran");

    // The model retries before the person approved: refused, the approval stays open.
    let mut with_id = args.clone();
    with_id[APPROVAL_ARG] = json!(id);
    let early = call(&f.app, ANA, "payments_refund", with_id.clone()).await;
    assert!(
        early["result"]["content"][0]["text"]
            .as_str()
            .unwrap()
            .contains("not approved it yet"),
        "{early}"
    );

    // Another person can neither see nor confirm Ana's approval.
    let (s, _, _) = send(
        &f.app,
        "GET",
        &format!("/mcp/approvals/{id}"),
        Some(BOB),
        None,
    )
    .await;
    assert_eq!(s, StatusCode::NOT_FOUND);
    let (s, _, _) = send(
        &f.app,
        "POST",
        &format!("/mcp/approvals/{id}"),
        Some(BOB),
        None,
    )
    .await;
    assert_eq!(s, StatusCode::NOT_FOUND);

    // The app shows Ana what she approves, and confirms with her token.
    let (s, shown, _) = send(
        &f.app,
        "GET",
        &format!("/mcp/approvals/{id}"),
        Some(ANA),
        None,
    )
    .await;
    assert_eq!(s, StatusCode::OK);
    assert_eq!(shown["tool"], "payments_refund");
    assert_eq!(shown["arguments"], args);
    let (s, _, _) = send(
        &f.app,
        "POST",
        &format!("/mcp/approvals/{id}"),
        Some(ANA),
        None,
    )
    .await;
    assert_eq!(s, StatusCode::OK);

    let done = call(&f.app, ANA, "payments_refund", with_id.clone()).await;
    assert_eq!(done["result"]["isError"], false, "{done}");
    assert_eq!(done["result"]["structuredContent"]["by"], "ana");
    assert_eq!(
        f.service.refunds.lock().unwrap().clone(),
        vec![("ana".to_owned(), "P-1".to_owned(), 500)]
    );

    // Single use.
    let again = call(&f.app, ANA, "payments_refund", with_id).await;
    assert_eq!(again["result"]["isError"], true);
    assert_eq!(f.service.refunds.lock().unwrap().len(), 1);

    let outcomes: Vec<String> = audit.entries().iter().map(|e| e.outcome.clone()).collect();
    assert_eq!(
        outcomes,
        vec![
            "approval_required",
            "approval_refused",
            "approved",
            "started",
            "ok",
            "approval_refused"
        ]
    );
    // The arguments are a digest in the record, never in clear.
    for e in audit.entries() {
        assert!(!format!("{e:?}").contains("P-1"), "{e:?}");
    }
}

#[tokio::test]
async fn an_approval_covers_only_the_arguments_that_were_approved() {
    let f = fixture_with(|b| b);
    let first = call(
        &f.app,
        ANA,
        "payments_refund",
        json!({"payment": "P-1", "amount_cents": 500}),
    )
    .await;
    let id = first["result"]["structuredContent"]["approval_required"]["id"]
        .as_str()
        .unwrap()
        .to_owned();
    send(
        &f.app,
        "POST",
        &format!("/mcp/approvals/{id}"),
        Some(ANA),
        None,
    )
    .await;
    // The model changes the amount after the approval: refused, and the approval is spent.
    let changed = call(
        &f.app,
        ANA,
        "payments_refund",
        json!({"payment": "P-1", "amount_cents": 50000, APPROVAL_ARG: id}),
    )
    .await;
    assert!(
        changed["result"]["content"][0]["text"]
            .as_str()
            .unwrap()
            .contains("differ"),
        "{changed}"
    );
    let original = call(
        &f.app,
        ANA,
        "payments_refund",
        json!({"amount_cents": 500, "payment": "P-1", APPROVAL_ARG: id}),
    )
    .await;
    assert_eq!(original["result"]["isError"], true);
    assert!(f.service.refunds.lock().unwrap().is_empty());
}

#[tokio::test]
async fn auto_approve_is_an_explicit_exception() {
    let f = fixture_with(|b| b.auto_approve("payments_refund", "payments.refund.auto"));
    let res = call(
        &f.app,
        BOB,
        "payments_refund",
        json!({"payment": "P-2", "amount_cents": 100}),
    )
    .await;
    assert_eq!(res["result"]["isError"], false, "{res}");
    // Ana lacks the auto permission: she still needs an approval.
    let res = call(
        &f.app,
        ANA,
        "payments_refund",
        json!({"payment": "P-3", "amount_cents": 100}),
    )
    .await;
    assert!(res["result"]["structuredContent"]["approval_required"].is_object());
    assert_eq!(f.service.refunds.lock().unwrap().len(), 1);
}

struct FailingAudit;

#[async_trait::async_trait]
impl AuditSink for FailingAudit {
    async fn record(&self, _: &AuditEntry) -> PortResult<()> {
        Err("audit store down".into())
    }
}

#[tokio::test]
async fn a_write_that_cannot_be_audited_does_not_run() {
    let f = fixture_audit(Arc::new(FailingAudit), |b| {
        b.auto_approve("payments_refund", "payments.refund.auto")
    });
    let res = call(
        &f.app,
        BOB,
        "payments_refund",
        json!({"payment": "P-9", "amount_cents": 100}),
    )
    .await;
    assert_eq!(res["result"]["isError"], true);
    assert!(f.service.refunds.lock().unwrap().is_empty());
}

#[tokio::test]
async fn the_transport_rules_hold() {
    let f = fixture_with(|b| {
        b.allow_origin("https://app.example.com")
            .authorization_server("https://auth.example.com")
    });
    // No token: 401 with the protected-resource metadata pointer.
    let (s, _, headers) = send(
        &f.app,
        "POST",
        "/mcp",
        None,
        Some(json!({"jsonrpc": "2.0", "id": 1, "method": "ping"})),
    )
    .await;
    assert_eq!(s, StatusCode::UNAUTHORIZED);
    assert_eq!(
        headers["www-authenticate"],
        "Bearer resource_metadata=\"https://api.example.com/.well-known/oauth-protected-resource\""
    );
    let (s, meta, _) = send(
        &f.app,
        "GET",
        "/.well-known/oauth-protected-resource",
        None,
        None,
    )
    .await;
    assert_eq!(s, StatusCode::OK);
    assert_eq!(
        meta["authorization_servers"],
        json!(["https://auth.example.com"])
    );

    // A browser origin that is not allowed is refused (DNS rebinding).
    let req = |origin: &str| {
        Request::builder()
            .method("POST")
            .uri("/mcp")
            .header("authorization", format!("Bearer {ANA}"))
            .header("origin", origin)
            .body(Body::from(
                json!({"jsonrpc": "2.0", "id": 1, "method": "ping"}).to_string(),
            ))
            .unwrap()
    };
    assert_eq!(
        f.app
            .clone()
            .oneshot(req("https://evil.example"))
            .await
            .unwrap()
            .status(),
        StatusCode::FORBIDDEN
    );
    assert_eq!(
        f.app
            .clone()
            .oneshot(req("https://app.example.com"))
            .await
            .unwrap()
            .status(),
        StatusCode::OK
    );

    // A notification is accepted; a batch and an unknown method are errors.
    let (s, _, _) = send(
        &f.app,
        "POST",
        "/mcp",
        Some(ANA),
        Some(json!({"jsonrpc": "2.0", "method": "notifications/initialized"})),
    )
    .await;
    assert_eq!(s, StatusCode::ACCEPTED);
    let (_, batch, _) = send(
        &f.app,
        "POST",
        "/mcp",
        Some(ANA),
        Some(json!([{"jsonrpc": "2.0", "id": 1, "method": "ping"}])),
    )
    .await;
    assert_eq!(batch["error"]["code"], -32600);
    let unknown = rpc(&f.app, ANA, "resources/list", json!({})).await;
    assert_eq!(unknown["error"]["code"], -32601);
    let (s, _, _) = send(&f.app, "GET", "/mcp", Some(ANA), None).await;
    assert_eq!(s, StatusCode::METHOD_NOT_ALLOWED);
}
